import {useCallback,useEffect,useState,type FormEvent,type ReactNode} from 'react';
import {ArrowClockwise,ArrowRight,Check,CirclesThreePlus,Coin,Copy,DownloadSimple,Handshake,House,Money,Percent,ShieldCheck,SignOut,Ticket,UsersThree,WarningCircle} from '@phosphor-icons/react';
import {api,formatMoney,loadSession,setCsrf,type AppRole,type SessionUser} from './api';
import {Brand,navigate} from './App';
import './commerce-portals.css';
import './ops-controls.css';

type AdminTab='Overview'|'Coupons'|'Influencers'|'Orders'|'Finance'|'Users'|'Settings'|'Audit';
type UnknownRow=Record<string,unknown>;
interface DashboardMetrics{users:number;orders:number;revenue:{currency:string;cents:number}[];discounts:{currency:string;cents:number}[];commissionLiabilityCents:number;pendingInfluencers:number}

function Field({label,helper,children}:{label:string;helper?:string;children:ReactNode}){return <label className="ops-field"><span>{label}</span>{children}{helper&&<small>{helper}</small>}</label>}
function Message({children,error=false}:{children:ReactNode;error?:boolean}){return <p className={`ops-message ${error?'error':''}`} role={error?'alert':'status'}>{error?<WarningCircle size={17}/>:<Check size={17}/>} {children}</p>}
function Empty({title,body}:{title:string;body:string}){return <div className="ops-empty"><CirclesThreePlus size={29}/><h3>{title}</h3><p>{body}</p></div>}
function Skeleton(){return <div className="ops-skeleton" aria-label="Loading"><i/><i/><i/></div>}

function AuthPanel({allowed,onAuthenticated,title,otpArea}:{allowed:AppRole[];onAuthenticated:(user:SessionUser)=>void;title:string;otpArea:'admin'|'partner'}){
 const [step,setStep]=useState<'email'|'code'>('email');const [email,setEmail]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [message,setMessage]=useState('');
 async function submitEmail(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError('');try{const result=await api<{message:string}>('/api/auth/otp/request',{method:'POST',body:JSON.stringify({email,purpose:otpArea})});setMessage(result.message);setStep('code');}catch(reason){setError(reason instanceof Error?reason.message:'Could not send the code');}finally{setBusy(false)}}
 async function submitCode(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError('');const data=new FormData(event.currentTarget);try{const result=await api<{user:SessionUser}>('/api/auth/otp/verify',{method:'POST',body:JSON.stringify({email,code:data.get('code'),purpose:otpArea})});setCsrf(result.user.csrfToken);if(!allowed.includes(result.user.role))throw new Error('This account does not have access to this area.');onAuthenticated(result.user);}catch(reason){setError(reason instanceof Error?reason.message:'Could not sign in');}finally{setBusy(false)}}
 return <main className="ops-auth"><section><Brand/><span className="ops-kicker"><ShieldCheck size={17}/> Email protected access</span><h1>{title}</h1><p>Enter your approved email address. We will send a single-use sign-in code that expires in 10 minutes.</p>{step==='email'?<form onSubmit={submitEmail}><Field label="Email"><input value={email} onChange={event=>setEmail(event.target.value)} name="email" type="email" required autoComplete="email" autoFocus/></Field>{error&&<Message error>{error}</Message>}<button className="ops-primary" disabled={busy}>{busy?'Sending':'Email me a code'} <ArrowRight/></button></form>:<form onSubmit={submitCode}><Field label="Six-digit code" helper={`Sent to ${email}`}><input name="code" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code" autoFocus/></Field>{message&&<Message>{message}</Message>}{error&&<Message error>{error}</Message>}<button className="ops-primary" disabled={busy}>{busy?'Verifying':'Verify and sign in'} <ArrowRight/></button><button type="button" className="ops-switch" onClick={()=>{setStep('email');setError('');setMessage('')}}>Use a different email</button></form>}<button className="ops-home" onClick={()=>navigate('/')}><House/> Back to Vowvel</button></section></main>
}

function Metric({label,value,icon}:{label:string;value:string;icon:ReactNode}){return <div className="ops-metric"><span>{icon}{label}</span><strong>{value}</strong></div>}

function OpsModal({title,intro,onClose,children}:{title:string;intro:string;onClose:()=>void;children:ReactNode}){
  useEffect(()=>{const onKey=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose()};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[onClose]);
  return <div className="ops-modal-backdrop" onClick={onClose}><div className="ops-modal" role="dialog" aria-modal="true" aria-label={title} onClick={event=>event.stopPropagation()}><div className="ops-modal-head"><div><h3>{title}</h3><p>{intro}</p></div><button className="ops-secondary" onClick={onClose}>Close</button></div>{children}</div></div>
}

function scheduleText(row:UnknownRow):string{
  const fmt=(value:unknown)=>{if(typeof value!=='string'||!value)return '';const time=new Date(value).getTime();return Number.isFinite(time)?new Date(time).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):''};
  const start=fmt(row.starts_at);const end=fmt(row.ends_at);
  if(start&&end)return `${start} → ${end}`;if(start)return `From ${start}`;if(end)return `Until ${end}`;return 'Always on';
}

function BatchDialog({campaign,onClose,onDone}:{campaign:UnknownRow;onClose:()=>void;onDone:()=>void}){
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [result,setResult]=useState<{batchId:string;codes:string[]}|null>(null);const [copied,setCopied]=useState(false);const [recent,setRecent]=useState<UnknownRow[]|null>(null);
  useEffect(()=>{api<{codes:UnknownRow[]}>(`/api/admin/coupons/${String(campaign.id)}/codes`).then(response=>setRecent(response.codes)).catch(()=>setRecent([]))},[campaign.id]);
  async function submit(event:FormEvent<HTMLFormElement>){
    event.preventDefault();if(busy)return;setBusy(true);setError('');setCopied(false);
    const data=new FormData(event.currentTarget);const count=Number(data.get('count'));const length=Number(data.get('length')||10);const unlimited=data.get('unlimited')==='on';const uses=Number(data.get('uses'));
    if(!Number.isInteger(count)||count<1||count>500){setError('Count must be a whole number between 1 and 500.');setBusy(false);return}
    if(!Number.isInteger(length)||length<6||length>24){setError('Code length must be between 6 and 24 characters.');setBusy(false);return}
    if(!unlimited&&(!Number.isInteger(uses)||uses<1)){setError('Uses per code must be at least 1, or tick unlimited.');setBusy(false);return}
    try{
      const response=await api<{batchId:string;codes:string[]}>(`/api/admin/coupons/${String(campaign.id)}/batch`,{method:'POST',body:JSON.stringify({prefix:String(data.get('prefix')||''),count,length,maxRedemptions:unlimited?null:uses})});
      setResult({batchId:response.batchId,codes:response.codes});onDone();
    }catch(reason){setError(reason instanceof Error?reason.message:'Could not generate batch')}finally{setBusy(false)}
  }
  function download(){
    if(!result)return;const csv=['code',...result.codes].map(code=>`"${code.replace(/"/g,'""')}"`).join('\n');
    const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`coupon-batch-${String(campaign.id)}.csv`;document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  async function copyAll(){if(!result)return;try{await navigator.clipboard.writeText(result.codes.join('\n'));setCopied(true);setTimeout(()=>setCopied(false),1600)}catch{setError('Copy failed. Select the codes from the list manually.')}}
  return <OpsModal title={`Batch codes · ${String(campaign.name)}`} intro={String(campaign.status)==='active'?'Codes work immediately on an active campaign.':'This campaign is not active — generated codes stay dormant until it is activated.'} onClose={onClose}>
    {error&&<Message error>{error}</Message>}
    {result?<div className="ops-batch-result"><Message>{result.codes.length} codes generated in batch {result.batchId}.</Message><ol className="ops-code-list">{result.codes.map(code=><li key={code}>{code}</li>)}</ol><div className="ops-inline-actions"><button className="ops-primary" onClick={()=>void copyAll()}><Copy/> {copied?'Copied':'Copy all'}</button><button className="ops-secondary" onClick={download}><DownloadSimple/> Download CSV</button><button className="ops-secondary" onClick={onClose}>Done</button></div></div>:
    <form className="ops-dialog-form" onSubmit={submit}>
      <Field label="Code prefix (optional)" helper="Letters and numbers, up to 12 characters."><input name="prefix" maxLength={12} placeholder="VOW" autoComplete="off"/></Field>
      <Field label="How many codes" helper="1 to 500 per batch."><input name="count" type="number" min={1} max={500} step={1} defaultValue={10} required/></Field>
      <Field label="Code length" helper="Random characters after the prefix, 6 to 24."><input name="length" type="number" min={6} max={24} step={1} defaultValue={10} required/></Field>
      <Field label="Uses per code"><input name="uses" type="number" min={1} step={1} defaultValue={1}/></Field>
      <Field label="Usage"><span className="ops-checkbox"><input name="unlimited" type="checkbox"/> Unlimited uses per code</span></Field>
      <button className="ops-primary" type="submit" disabled={busy}>{busy?'Generating…':'Generate batch'} <Ticket/></button>
    </form>}
    <h4 className="ops-subhead">Recent codes ({recent===null?'loading…':recent.length})</h4>
    {recent===null?<Skeleton/>:recent.length===0?<p className="ops-muted-text">No codes issued for this campaign yet.</p>:<ol className="ops-code-list">{recent.slice(0,50).map(row=><li key={String(row.code)}><strong>{String(row.code)}</strong><small>{String(row.status)} · used {String(row.redeemed_count||0)}{row.max_redemptions?` of ${String(row.max_redemptions)}`:' · unlimited'}</small></li>)}</ol>}
  </OpsModal>
}

function StatusDialog({campaign,onClose,onDone}:{campaign:UnknownRow;onClose:()=>void;onDone:()=>void}){
  const current=String(campaign.status);const [status,setStatus]=useState(current);const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){
    event.preventDefault();if(busy)return;
    if(status===current){onClose();return}
    if(reason.trim().length<3){setError('A short reason is required. It is written to the audit log.');return}
    setBusy(true);setError('');
    try{await api(`/api/admin/coupons/${String(campaign.id)}`,{method:'PATCH',body:JSON.stringify({status,reason:reason.trim()})});onDone();onClose()}catch(failure){setError(failure instanceof Error?failure.message:'Could not update campaign')}finally{setBusy(false)}
  }
  return <OpsModal title={`Campaign status · ${String(campaign.name)}`} intro={`Currently ${current}. Pausing stops all redemptions immediately; expiring is permanent in effect but reversible here.`} onClose={onClose}>
    {error&&<Message error>{error}</Message>}
    <form className="ops-dialog-form" onSubmit={submit}>
      <Field label="New status"><select value={status} onChange={event=>setStatus(event.target.value)}><option value="draft">Draft</option><option value="active">Active</option><option value="paused">Paused</option><option value="expired">Expired</option></select></Field>
      <Field label="Reason (audit log)" helper="Required. Explain why this change is safe."><textarea name="reason" rows={2} value={reason} onChange={event=>setReason(event.target.value)} placeholder="e.g. Festive offer ended 14 Feb; redemptions at zero"/></Field>
      <button className="ops-primary" type="submit" disabled={busy}>{busy?'Saving…':'Confirm status change'}</button>
    </form>
  </OpsModal>
}

function SearchInput({value,onChange,label}:{value:string;onChange:(value:string)=>void;label:string}){return <label className="ops-search"><span className="ops-search-label">{label}</span><input value={value} onChange={event=>onChange(event.target.value)} placeholder="Type to filter…" autoComplete="off"/></label>}

function fmtDateTime(value:unknown):string{
  if(typeof value!=='string'||!value)return '—';
  const time=new Date(value).getTime();if(!Number.isFinite(time))return '—';
  return new Date(time).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
}

function inviteHref(row:UnknownRow):string|null{
  const sub=String(row.custom_subdomain||'');if(sub)return `https://${sub}.vowvel.com`;
  const slug=String(row.invitation_slug||row.slug||'');if(slug)return `/#/invite/${slug}`;
  return null;
}

function ReviewDialog({influencer,onClose,onDone}:{influencer:UnknownRow;onClose:()=>void;onDone:()=>void}){
  const [status,setStatus]=useState('approved');const [reason,setReason]=useState('');const [prefix,setPrefix]=useState('VOW');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){
    event.preventDefault();if(busy)return;
    if(reason.trim().length<3){setError('A short reason is required. It is written to the audit log.');return}
    setBusy(true);setError('');
    try{await api(`/api/admin/influencers/${String(influencer.id)}`,{method:'PATCH',body:JSON.stringify({status,reason:reason.trim(),codePrefix:prefix})});onDone();onClose()}catch(failure){setError(failure instanceof Error?failure.message:'Review failed')}finally{setBusy(false)}
  }
  return <OpsModal title={`Review · ${String(influencer.name)}`} intro={`${String(influencer.email)} · audience ${Number(influencer.audience_size||0).toLocaleString('en-IN')}. Approval issues a partner coupon immediately.`} onClose={onClose}>
    {error&&<Message error>{error}</Message>}
    <form className="ops-dialog-form" onSubmit={submit}>
      <Field label="Decision"><select value={status} onChange={event=>setStatus(event.target.value)}><option value="approved">Approve</option><option value="suspended">Suspend</option><option value="rejected">Reject</option></select></Field>
      {status==='approved'&&<Field label="Coupon prefix" helper="Up to 12 letters or numbers."><input value={prefix} maxLength={12} onChange={event=>setPrefix(event.target.value)} autoComplete="off"/></Field>}
      <Field label="Reason (audit log)" helper="Required. Rejections and suspensions especially need a clear reason."><textarea rows={2} value={reason} onChange={event=>setReason(event.target.value)} placeholder="e.g. Genuine wedding audience, consistent posting"/></Field>
      <button className="ops-primary" type="submit" disabled={busy}>{busy?'Saving…':'Confirm decision'}</button>
    </form>
  </OpsModal>
}

function RefundDialog({order,onClose,onDone}:{order:UnknownRow;onClose:()=>void;onDone:()=>void}){
  const total=Number(order.total_cents||0);const currency=String(order.currency||'INR');
  const [amountText,setAmountText]=useState('');const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){
    event.preventDefault();if(busy)return;
    const trimmed=amountText.trim();const amount=trimmed===''?undefined:Math.round(Number(trimmed)*100);
    if(amount!==undefined&&(!Number.isFinite(amount)||amount<=0)){setError(`Enter a valid amount in ${currency}, or leave blank for a full refund.`);return}
    if(amount!==undefined&&amount>total){setError(`Amount cannot exceed the order total of ${formatMoney(total,currency)}.`);return}
    if(reason.trim().length<3){setError('A refund reason is required. It is written to the audit log.');return}
    setBusy(true);setError('');
    try{await api(`/api/admin/orders/${String(order.id)}/refund`,{method:'POST',body:JSON.stringify({amountCents:amount,reason:reason.trim()})});onDone();onClose()}catch(failure){setError(failure instanceof Error?failure.message:'Refund could not be processed')}finally{setBusy(false)}
  }
  return <OpsModal title={`Refund · ${String(order.id)}`} intro={`Order total ${formatMoney(total,currency)} via ${String(order.provider||'unknown provider')}. Partial refunds adjust commission entries proportionally.`} onClose={onClose}>
    {error&&<Message error>{error}</Message>}
    <form className="ops-dialog-form" onSubmit={submit}>
      <Field label={`Amount (${currency})`} helper="Leave blank for the full remaining amount."><input value={amountText} onChange={event=>setAmountText(event.target.value)} inputMode="decimal" placeholder="Full refund" autoComplete="off"/></Field>
      <Field label="Reason (audit log)" helper="Required."><textarea rows={2} value={reason} onChange={event=>setReason(event.target.value)} placeholder="e.g. Duplicate charge, customer requested cancellation"/></Field>
      <button className="ops-primary danger" type="submit" disabled={busy}>{busy?'Processing…':amountText.trim()===''?'Refund in full':'Confirm refund'}</button>
    </form>
  </OpsModal>
}

function PayoutDialog({partner,onClose,onDone}:{partner:UnknownRow;onClose:()=>void;onDone:()=>void}){
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){
    event.preventDefault();if(busy)return;setBusy(true);setError('');
    try{await api('/api/admin/payouts',{method:'POST',body:JSON.stringify({influencerId:String(partner.id)})});onDone();onClose()}catch(failure){setError(failure instanceof Error?failure.message:'Could not create payout')}finally{setBusy(false)}
  }
  return <OpsModal title={`Create payout · ${String(partner.name)}`} intro={`Batches ${formatMoney(partner.available_cents)} of available commission into one payout. Ledger entries move to approved; this cannot be undone, only reversed through payout status.`} onClose={onClose}>
    {error&&<Message error>{error}</Message>}
    <form className="ops-dialog-form" onSubmit={submit}>
      <button className="ops-primary" type="submit" disabled={busy}>{busy?'Creating…':`Confirm payout of ${formatMoney(partner.available_cents)}`}</button>
    </form>
  </OpsModal>
}

function MarkPaidDialog({payout,onClose,onDone}:{payout:UnknownRow;onClose:()=>void;onDone:()=>void}){
  const [reference,setReference]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){
    event.preventDefault();if(busy)return;
    if(reference.trim().length<3){setError('Enter the bank or UPI reference from the actual transfer.');return}
    setBusy(true);setError('');
    try{await api(`/api/admin/payouts/${String(payout.id)}`,{method:'PATCH',body:JSON.stringify({status:'paid',reference:reference.trim(),reason:`Marked paid by finance, ref ${reference.trim()}`})});onDone();onClose()}catch(failure){setError(failure instanceof Error?failure.message:'Could not mark payout paid')}finally{setBusy(false)}
  }
  return <OpsModal title={`Mark paid · ${formatMoney(payout.amount_cents)}`} intro={`Record this only after the money has actually left your account to ${String(payout.name)}.`} onClose={onClose}>
    {error&&<Message error>{error}</Message>}
    <form className="ops-dialog-form" onSubmit={submit}>
      <Field label="Bank / UPI reference" helper="Required. From the completed transfer."><input value={reference} onChange={event=>setReference(event.target.value)} placeholder="UTR or UPI ref" autoComplete="off"/></Field>
      <button className="ops-primary" type="submit" disabled={busy}>{busy?'Saving…':'Confirm money sent'}</button>
    </form>
  </OpsModal>
}

function CouponPanel({reloadKey,onChanged}:{reloadKey:number;onChanged:()=>void}){
  const [rows,setRows]=useState<UnknownRow[]>([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [created,setCreated]=useState('');const [dialog,setDialog]=useState<null|{type:'batch'|'status';campaign:UnknownRow}>(null);
 const load=useCallback(async()=>{setLoading(true);setError('');try{const result=await api<{campaigns:UnknownRow[]}>('/api/admin/coupons');setRows(result.campaigns);}catch(reason){setError(reason instanceof Error?reason.message:'Could not load coupons');}finally{setLoading(false)}},[]);
 useEffect(()=>{void load()},[load,reloadKey]);
  async function create(event:FormEvent<HTMLFormElement>){
    event.preventDefault();if(busy)return;setBusy(true);setError('');setCreated('');
    const form=event.currentTarget;const data=new FormData(form);
    const discountKind=String(data.get('discountType'));const rawValue=Number(data.get('discountValue'));
    if(!Number.isFinite(rawValue)||rawValue<=0){setError('Enter a discount above zero.');setBusy(false);return}
    if(discountKind==='percentage'&&rawValue>100){setError('Percentage discounts cannot exceed 100%.');setBusy(false);return}
    const startsRaw=String(data.get('startsAt')||'');const endsRaw=String(data.get('endsAt')||'');
    if(startsRaw&&endsRaw&&new Date(endsRaw).getTime()<=new Date(startsRaw).getTime()){setError('End date must be after the start date.');setBusy(false);return}
    const iso=(name:string)=>{const value=String(data.get(name)||'');return value?new Date(value).toISOString():null};
    try{const result=await api<{id:string}>('/api/admin/coupons',{method:'POST',body:JSON.stringify({name:data.get('name'),description:data.get('description'),status:data.get('status'),discountType:data.get('discountType'),discountValue:rawValue*100,maxDiscountCents:data.get('maxDiscount')?Number(data.get('maxDiscount'))*100:null,minSubtotalCents:Number(data.get('minimum')||0)*100,startsAt:iso('startsAt'),endsAt:iso('endsAt'),globalLimit:data.get('globalLimit')?Number(data.get('globalLimit')):null,perCustomerLimit:Number(data.get('perCustomer')||1),firstPurchaseOnly:data.get('firstPurchaseOnly')==='on',commissionBps:Number(data.get('commission')||0)*100})});setCreated(String(data.get('name')));form.reset();await load();onChanged();}catch(reason){setError(reason instanceof Error?reason.message:'Could not create campaign')}finally{setBusy(false)}
  }
  /* Batch generation and status changes run through audited dialogs (BatchDialog, StatusDialog). */
 return <div className="ops-module"><div className="ops-module-head"><div><h2>Coupon studio</h2><p>Create percentage or fixed-value campaigns, schedule availability and issue secure code batches.</p></div><button className="ops-secondary" onClick={()=>void load()}><ArrowClockwise/> Refresh</button></div><form className="ops-form-grid" onSubmit={create}><Field label="Campaign name"><input name="name" required/></Field><Field label="Status"><select name="status" defaultValue="active"><option value="active">Active</option><option value="draft">Draft</option><option value="paused">Paused</option></select></Field><Field label="Discount type"><select name="discountType"><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></Field><Field label="Discount value" helper="Enter 10 for 10% or 250 for ₹250."><input name="discountValue" type="number" min="0.01" step="0.01" required/></Field><Field label="Maximum discount (₹)" helper="Optional cap, useful for percentage offers."><input name="maxDiscount" type="number" min="0.01" step="0.01"/></Field><Field label="Minimum order (₹)"><input name="minimum" type="number" min="0" defaultValue="0"/></Field><Field label="Starts at"><input name="startsAt" type="datetime-local"/></Field><Field label="Ends at"><input name="endsAt" type="datetime-local"/></Field><Field label="Global redemption limit"><input name="globalLimit" type="number" min="1"/></Field><Field label="Uses per customer"><input name="perCustomer" type="number" min="1" defaultValue="1"/></Field><Field label="Partner commission (%)"><input name="commission" type="number" min="0" max="100" step="0.01" defaultValue="0"/></Field><Field label="Eligibility"><span className="ops-checkbox"><input name="firstPurchaseOnly" type="checkbox"/> First purchase only</span></Field><Field label="Internal description"><input name="description"/></Field><button className="ops-primary" type="submit" disabled={busy}>{busy?'Creating…':<span><Ticket/> Create campaign</span>}</button></form>{created&&<Message>Campaign “{created}” created. Use Batch on its row to issue the first codes.</Message>}{error&&<Message error>{error}</Message>}{loading?<Skeleton/>:rows.length===0?<Empty title="No campaigns yet" body="Create the first campaign using the form above."/>:<div className="ops-table-wrap"><table><thead><tr><th>Campaign</th><th>Rule</th><th>Schedule</th><th>Status</th><th>Codes</th><th>Used</th><th>Controls</th></tr></thead><tbody>{rows.map(row=><tr key={String(row.id)}><td><strong>{String(row.name)}</strong><small>{String(row.description||'No description')}</small></td><td><strong>{String(row.discount_type)==='percentage'?`${Number(row.discount_value)/100}%`:formatMoney(row.discount_value)}</strong><small>{[row.max_discount_cents?`Cap ${formatMoney(row.max_discount_cents)}`:'',Number(row.min_subtotal_cents||0)>0?`Min ${formatMoney(row.min_subtotal_cents)}`:''].filter(Boolean).join(' · ')||'No caps'}</small></td><td><small>{scheduleText(row)}</small></td><td><span className={`ops-status ${String(row.status)}`}>{String(row.status)}</span></td><td>{String(row.code_count||0)}</td><td>{String(row.redemption_count||0)}</td><td><div className="ops-inline-actions"><button className="ops-row-action" onClick={()=>setDialog({type:'batch',campaign:row})}><DownloadSimple/> Batch</button><button className="ops-row-action" onClick={()=>setDialog({type:'status',campaign:row})}>Status…</button></div></td></tr>)}</tbody></table></div>}{dialog?.type==='batch'&&<BatchDialog campaign={dialog.campaign} onClose={()=>setDialog(null)} onDone={()=>{void load();onChanged()}}/>}{dialog?.type==='status'&&<StatusDialog campaign={dialog.campaign} onClose={()=>setDialog(null)} onDone={()=>{void load();onChanged()}}/>}</div>
}

function InfluencerPanel(){
 const [rows,setRows]=useState<UnknownRow[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [filter,setFilter]=useState('all');const [dialog,setDialog]=useState<UnknownRow|null>(null);
 const load=useCallback(async()=>{setLoading(true);try{const result=await api<{influencers:UnknownRow[]}>('/api/admin/influencers');setRows(result.influencers);}catch(reason){setError(reason instanceof Error?reason.message:'Could not load influencers');}finally{setLoading(false)}},[]);useEffect(()=>{void load()},[load]);
 const channels=(row:UnknownRow)=>{try{const list=JSON.parse(String(row.channels_json||'[]'));return Array.isArray(list)?list.map(String).filter(Boolean):[]}catch{return[]}};
 const visible=rows.filter(row=>filter==='all'||String(row.status)===filter);
 return <div className="ops-module"><div className="ops-module-head"><div><h2>Influencer collaboration</h2><p>Review applications, issue partner codes and monitor unpaid balances. Approval issues a coupon immediately.</p></div><div className="ops-head-actions"><select value={filter} onChange={event=>setFilter(event.target.value)} aria-label="Filter by status"><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="suspended">Suspended</option><option value="rejected">Rejected</option></select><button className="ops-secondary" onClick={()=>void load()}><ArrowClockwise/> Refresh</button></div></div>{error&&<Message error>{error}</Message>}{loading?<Skeleton/>:visible.length===0?<Empty title="No matches" body="No influencers match this filter."/>:<div className="ops-partner-list">{visible.map(row=><article key={String(row.id)}><div><span className={`ops-status ${String(row.status)}`}>{String(row.status)}</span><h3>{String(row.name)}</h3><p>{String(row.email)}</p><small>{String(row.bio||'No bio provided')}</small><small>Channels: {channels(row).join(', ')||'—'}</small></div><dl><div><dt>Audience</dt><dd>{Number(row.audience_size||0).toLocaleString('en-IN')}</dd></div><div><dt>Coupon</dt><dd>{String(row.code||'Not assigned')}</dd></div><div><dt>Available</dt><dd>{formatMoney(row.available_cents)}</dd></div><div><dt>Pending</dt><dd>{formatMoney(row.pending_cents)}</dd></div></dl><div className="ops-review-actions"><button onClick={()=>setDialog(row)}><Check/> Review</button></div></article>)}</div>}{dialog&&<ReviewDialog influencer={dialog} onClose={()=>setDialog(null)} onDone={()=>void load()}/>}</div>
}

function AuditPanel(){
 const [rows,setRows]=useState<UnknownRow[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [query,setQuery]=useState('');
 const load=useCallback(async(search:string)=>{setLoading(true);try{const result=await api<{events:UnknownRow[]}>(`/api/admin/audit${search.trim()?`?q=${encodeURIComponent(search.trim())}`:''}`);setRows(result.events);}catch(reason){setError(reason instanceof Error?reason.message:'Could not load records');}finally{setLoading(false)}},[]);useEffect(()=>{void load('')},[load]);
 useEffect(()=>{const timer=setTimeout(()=>{void load(query)},350);return()=>clearTimeout(timer)},[query,load]);
 const pretty=(value:unknown)=>{if(value===null||value===undefined||value==='')return '—';try{return JSON.stringify(typeof value==='string'?JSON.parse(value):value,null,1)}catch{return String(value)}};
 return <div className="ops-module"><div className="ops-module-head"><div><h2>Audit events</h2><p>Immutable history for sensitive operations. Expand a row to inspect before and after values. Search by action or actor email.</p></div><div className="ops-head-actions"><SearchInput value={query} onChange={setQuery} label="Search audit"/><button className="ops-secondary" onClick={()=>void load(query)}><ArrowClockwise/> Refresh</button></div></div>{error&&<Message error>{error}</Message>}{loading?<Skeleton/>:rows.length===0?<Empty title="No audit events" body="No events match this search."/>:<div className="ops-table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th><th>Reason</th><th/></tr></thead><tbody>{rows.map((row,index)=><tr key={String(row.id||index)}><td><small>{fmtDateTime(row.created_at)}</small></td><td>{String(row.actor_email||'system')}</td><td><strong>{String(row.action)}</strong></td><td><small>{String(row.target_type)} · {String(row.target_id||'—')}</small></td><td><small>{String(row.reason||'—')}</small></td><td><details><summary className="ops-row-action">Details</summary><pre className="ops-json">{`before: ${pretty(row.before_json)}\nafter: ${pretty(row.after_json)}`}</pre></details></td></tr>)}</tbody></table></div>}</div>
}

function OrderPanel({canRefund,onChanged}:{canRefund:boolean;onChanged:()=>void}){
 const [rows,setRows]=useState<UnknownRow[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [message,setMessage]=useState('');const [query,setQuery]=useState('');const [dialog,setDialog]=useState<UnknownRow|null>(null);
 const load=useCallback(async(search:string)=>{setLoading(true);try{const result=await api<{orders:UnknownRow[]}>(`/api/admin/orders${search.trim()?`?q=${encodeURIComponent(search.trim())}`:''}`);setRows(result.orders);}catch(reason){setError(reason instanceof Error?reason.message:'Could not load orders');}finally{setLoading(false)}},[]);useEffect(()=>{void load('')},[load]);
 useEffect(()=>{const timer=setTimeout(()=>{void load(query)},350);return()=>clearTimeout(timer)},[query,load]);
 return <div className="ops-module"><div className="ops-module-head"><div><h2>Orders</h2><p>Server-authored totals, payment states and controlled full or partial refunds. Search by order id or customer email.</p></div><div className="ops-head-actions"><SearchInput value={query} onChange={setQuery} label="Search orders"/><button className="ops-secondary" onClick={()=>void load(query)}><ArrowClockwise/> Refresh</button></div></div>{error&&<Message error>{error}</Message>}{message&&<Message>{message}</Message>}{loading?<Skeleton/>:rows.length===0?<Empty title="No orders" body="No orders match this search."/>:<div className="ops-table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>State</th><th>Channel</th><th>Coupon</th><th>Total</th><th>Invitation</th><th>Created</th>{canRefund&&<th/>}</tr></thead><tbody>{rows.map(row=>{const href=inviteHref(row);return <tr key={String(row.id)}><td><strong>{String(row.id)}</strong></td><td>{String(row.email)}</td><td><span className={`ops-status ${String(row.state)}`}>{String(row.state)}</span></td><td><small>{String(row.provider||'—')} · {String(row.currency)}</small></td><td>{String(row.code||'')}</td><td>{formatMoney(row.total_cents,String(row.currency||'INR'))}</td><td>{href?<a href={href} target="_blank" rel="noreferrer">Open</a>:'—'}</td><td><small>{fmtDateTime(row.created_at)}</small></td>{canRefund&&<td>{['paid','partially_refunded'].includes(String(row.state))&&<button className="ops-row-action danger" onClick={()=>{setMessage('');setDialog(row)}}>Refund</button>}</td>}</tr>})}</tbody></table></div>}{dialog&&<RefundDialog order={dialog} onClose={()=>setDialog(null)} onDone={()=>{setMessage('Refund processed and related commission entries adjusted.');void load(query);onChanged()}}/>}</div>
}

function UserAccessRow({row,onSaved}:{row:UnknownRow;onSaved:()=>void}){const [error,setError]=useState('');const [reason,setReason]=useState('');const [armed,setArmed]=useState(false);const [busy,setBusy]=useState(false);async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();if(busy)return;const data=new FormData(event.currentTarget);if(!armed){if(reason.trim().length<3){setError('Add a short reason first. It is written to the audit log.');return}setArmed(true);return}setBusy(true);setError('');try{await api(`/api/admin/users/${String(row.id)}`,{method:'PATCH',body:JSON.stringify({role:data.get('role'),status:data.get('status'),reason:reason.trim()})});setError('');setArmed(false);onSaved();}catch(value){setError(value instanceof Error?value.message:'Access could not be updated')}finally{setBusy(false)}}return <tr><td><strong>{String(row.name)}</strong><small>{String(row.email)}</small>{error&&<small className="ops-cell-error">{error}</small>}</td><td colSpan={3}><form className="ops-access-form" onSubmit={save}><select name="role" defaultValue={String(row.role)} aria-label={`Role for ${String(row.name)}`} onChange={()=>setArmed(false)}><option value="owner">Owner</option><option value="admin">Admin</option><option value="finance">Finance</option><option value="support">Support</option><option value="content">Content</option><option value="influencer">Influencer</option><option value="customer">Customer</option></select><select name="status" defaultValue={String(row.status)} aria-label={`Status for ${String(row.name)}`} onChange={()=>setArmed(false)}><option value="active">Active</option><option value="pending">Pending</option><option value="suspended">Suspended</option><option value="disabled">Disabled</option></select><input name="reason" value={reason} onChange={event=>{setReason(event.target.value);setArmed(false)}} placeholder="Reason (audit log)" aria-label={`Reason for ${String(row.name)}`} autoComplete="off"/><button className="ops-row-action" type="submit" disabled={busy}>{busy?'Saving…':armed?'Confirm change':'Save access'}</button></form></td><td>{String(row.created_at)}</td></tr>}

function UsersPanel({canEdit}:{canEdit:boolean}){const [rows,setRows]=useState<UnknownRow[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [query,setQuery]=useState('');const load=useCallback(async(search:string)=>{setLoading(true);try{const result=await api<{users:UnknownRow[]}>(`/api/admin/users${search.trim()?`?q=${encodeURIComponent(search.trim())}`:''}`);setRows(result.users);}catch(reason){setError(reason instanceof Error?reason.message:'Could not load users');}finally{setLoading(false)}},[]);useEffect(()=>{void load('')},[load]);useEffect(()=>{const timer=setTimeout(()=>{void load(query)},350);return()=>clearTimeout(timer)},[query,load]);return <div className="ops-module"><div className="ops-module-head"><div><h2>User access</h2><p>Manage individual roles and account state. Changes need a reason and confirm. The final active Owner is protected from removal.</p></div><div className="ops-head-actions"><SearchInput value={query} onChange={setQuery} label="Search users"/><button className="ops-secondary" onClick={()=>void load(query)}><ArrowClockwise/> Refresh</button></div></div>{error&&<Message error>{error}</Message>}{loading?<Skeleton/>:rows.length===0?<Empty title="No users" body="No accounts match this search."/>:<div className="ops-table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Status</th>{canEdit&&<th>Control</th>}<th>Created</th></tr></thead><tbody>{rows.map(row=>canEdit?<UserAccessRow key={String(row.id)} row={row} onSaved={()=>void load(query)}/>:<tr key={String(row.id)}><td><strong>{String(row.name)}</strong><small>{String(row.email)}</small></td><td>{String(row.role)}</td><td>{String(row.status)}</td><td>{String(row.created_at)}</td></tr>)}</tbody></table></div>}</div>}

function FinancePanel({onChanged}:{onChanged:()=>void}){const [payouts,setPayouts]=useState<UnknownRow[]>([]);const [partners,setPartners]=useState<UnknownRow[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [payoutTarget,setPayoutTarget]=useState<UnknownRow|null>(null);const [paidTarget,setPaidTarget]=useState<UnknownRow|null>(null);const load=useCallback(async()=>{setLoading(true);try{const [payoutResult,partnerResult]=await Promise.all([api<{payouts:UnknownRow[]}>('/api/admin/payouts'),api<{influencers:UnknownRow[]}>('/api/admin/influencers')]);setPayouts(payoutResult.payouts);setPartners(partnerResult.influencers);}catch(reason){setError(reason instanceof Error?reason.message:'Could not load finance records')}finally{setLoading(false)}},[]);useEffect(()=>{void load()},[load]);
 /* Payout creation and paid-marking run through confirmed dialogs (PayoutDialog, MarkPaidDialog). */return <div className="ops-module"><div className="ops-module-head"><div><h2>Commission payouts</h2><p>Create payouts from available ledger entries and record the external transfer reference. Pending commission becomes available after the hold period.</p></div><button className="ops-secondary" onClick={()=>void load()}><ArrowClockwise/> Refresh</button></div>{error&&<Message error>{error}</Message>}{loading?<Skeleton/>:<><div className="ops-partner-list">{partners.filter(row=>Number(row.available_cents||0)>0).map(row=><article key={String(row.id)}><div><h3>{String(row.name)}</h3><p>{String(row.email)}</p></div><dl><div><dt>Available</dt><dd>{formatMoney(row.available_cents)}</dd></div><div><dt>Pending</dt><dd>{formatMoney(row.pending_cents)}</dd></div></dl><div className="ops-review-actions"><button onClick={()=>setPayoutTarget(row)}><Money/> Create payout</button></div></article>)}</div>{payouts.length===0?<Empty title="No payouts" body="Eligible partner balances can be batched above."/>:<div className="ops-table-wrap"><table><thead><tr><th>Partner</th><th>Amount</th><th>Status</th><th>Reference</th><th>Created</th><th/></tr></thead><tbody>{payouts.map(row=><tr key={String(row.id)}><td>{String(row.name)}<small>{String(row.email)}</small></td><td>{formatMoney(row.amount_cents)}</td><td><span className={`ops-status ${String(row.status)}`}>{String(row.status)}</span></td><td>{String(row.provider_reference||'')}</td><td><small>{fmtDateTime(row.created_at)}</small></td><td>{['approved','processing'].includes(String(row.status))&&<button className="ops-row-action" onClick={()=>setPaidTarget(row)}><Check/> Mark paid</button>}</td></tr>)}</tbody></table></div>}</>}{payoutTarget&&<PayoutDialog partner={payoutTarget} onClose={()=>setPayoutTarget(null)} onDone={()=>{void load();onChanged()}}/>}{paidTarget&&<MarkPaidDialog payout={paidTarget} onClose={()=>setPaidTarget(null)} onDone={()=>{void load();onChanged()}}/>}</div>}

function SettingsPanel(){const [settings,setSettings]=useState<UnknownRow|null>(null);const [error,setError]=useState('');const [message,setMessage]=useState('');const [reason,setReason]=useState('');const [armed,setArmed]=useState(false);const [busy,setBusy]=useState(false);useEffect(()=>{api<{commerce:UnknownRow}>('/api/admin/settings').then(result=>setSettings(result.commerce)).catch(reason=>setError(reason instanceof Error?reason.message:'Could not load settings'))},[]);async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();if(busy)return;if(!armed){if(reason.trim().length<3){setError('Add a short reason first. It is written to the audit log.');return}setArmed(true);return}setBusy(true);setError('');setMessage('');const data=new FormData(event.currentTarget);try{const result=await api<{commerce:UnknownRow}>('/api/admin/settings',{method:'PATCH',body:JSON.stringify({basePriceCents:Number(data.get('basePrice'))*100,currency:data.get('currency'),taxBps:Number(data.get('taxRate'))*100,commissionHoldDays:Number(data.get('holdDays')),minimumPayoutCents:Number(data.get('minimumPayout'))*100,reason:reason.trim()})});setSettings(result.commerce);setMessage('Commerce settings saved. New quotes use these values; open orders keep their snapshots.');setArmed(false);}catch(saveError){setError(saveError instanceof Error?saveError.message:'Could not save settings')}finally{setBusy(false)}}if(!settings)return <Skeleton/>;return <div className="ops-module"><div className="ops-module-head"><div><h2>Commerce settings</h2><p>These values control every new server-authored checkout quote and payout eligibility check. Changes apply instantly to new checkouts.</p></div></div><form className="ops-form-grid" onSubmit={save}><Field label="Base price (₹)"><input name="basePrice" type="number" min="1" step="0.01" defaultValue={Number(settings.basePriceCents)/100} onChange={()=>setArmed(false)}/></Field><Field label="Currency" helper="INR or USD — other codes are rejected."><select name="currency" defaultValue={String(settings.currency)} onChange={()=>setArmed(false)}><option value="INR">INR</option><option value="USD">USD</option></select></Field><Field label="Tax rate (%)"><input name="taxRate" type="number" min="0" max="100" step="0.01" defaultValue={Number(settings.taxBps)/100} onChange={()=>setArmed(false)}/></Field><Field label="Commission hold (days)"><input name="holdDays" type="number" min="0" max="365" defaultValue={Number(settings.commissionHoldDays)} onChange={()=>setArmed(false)}/></Field><Field label="Minimum payout (₹)"><input name="minimumPayout" type="number" min="1" defaultValue={Number(settings.minimumPayoutCents)/100} onChange={()=>setArmed(false)}/></Field><Field label="Reason (audit log)" helper="Required."><input name="reason" value={reason} onChange={event=>{setReason(event.target.value);setArmed(false)}} placeholder="Why is this change safe?" autoComplete="off"/></Field><button className="ops-primary" disabled={busy}>{busy?'Saving…':armed?'Confirm settings change':<span><Check/> Save settings</span>}</button></form>{error&&<Message error>{error}</Message>}{message&&<Message>{message}</Message>}</div>}

function AlertsPanel({onGo}:{onGo:(tab:AdminTab)=>void}){
 const [awaiting,setAwaiting]=useState<UnknownRow[]|null>(null);
 useEffect(()=>{api<{orders:UnknownRow[]}>('/api/admin/orders').then(response=>setAwaiting(response.orders.filter(row=>String(row.state)==='awaiting_payment'))).catch(()=>setAwaiting([]))},[]);
 if(!awaiting||awaiting.length===0)return null;
 const ages=awaiting.map(row=>Date.now()-new Date(String(row.created_at)).getTime()).filter(age=>Number.isFinite(age)&&age>=0);
 const oldestHours=ages.length?Math.max(...ages)/3_600_000:0;
 const stuck=oldestHours>1;
 return <div className="ops-alert" role="alert"><WarningCircle size={20}/><div><strong>{awaiting.length} order{awaiting.length===1?'':'s'} awaiting payment{stuck?`, oldest stuck ${Math.floor(oldestHours)}h`:''}.</strong><p>{stuck?'Payments verified but never captured usually mean a missing or failing payment webhook. Check webhook delivery, then complete or refund from Orders.':'These clear automatically when the payment webhook arrives.'}</p></div><button className="ops-secondary" onClick={()=>onGo('Orders')}>View orders</button></div>
}

export function AdminPortal(){
 const [user,setUser]=useState<SessionUser|null>(null);const [checking,setChecking]=useState(true);const [tab,setTab]=useState<AdminTab>('Overview');const [metrics,setMetrics]=useState<DashboardMetrics|null>(null);const [error,setError]=useState('');const [reloadKey,setReloadKey]=useState(0);
 const loadDashboard=useCallback(async()=>{try{const result=await api<{metrics:DashboardMetrics}>('/api/admin/dashboard');setMetrics(result.metrics);}catch(reason){setError(reason instanceof Error?reason.message:'Could not load dashboard')}},[]);
 function acceptUser(session:SessionUser){setUser(session);setTab(session.role==='support'?'Orders':'Overview')}
 useEffect(()=>{loadSession().then(session=>{if(session&&['owner','admin','finance','support'].includes(session.role))acceptUser(session)}).catch(()=>undefined).finally(()=>setChecking(false))},[]);useEffect(()=>{if(user&&['owner','admin','finance'].includes(user.role))void loadDashboard()},[user,loadDashboard,reloadKey]);
 async function logout(){if(user)await api('/api/auth/logout',{method:'POST'}).catch(()=>undefined);setUser(null)}
 if(checking)return <main className="ops-loading"><Skeleton/></main>;if(!user)return <AuthPanel allowed={['owner','admin','finance','support']} onAuthenticated={acceptUser} title="Run Vowvel with confidence." otpArea="admin"/>;
 const allowedTabs:Record<'owner'|'admin'|'finance'|'support',AdminTab[]>={owner:['Overview','Coupons','Influencers','Orders','Finance','Users','Settings','Audit'],admin:['Overview','Coupons','Influencers','Orders','Users','Settings','Audit'],finance:['Overview','Influencers','Orders','Finance'],support:['Orders','Users']};
 const allTabs:{name:AdminTab;icon:ReactNode}[]=[{name:'Overview',icon:<House/>},{name:'Coupons',icon:<Ticket/>},{name:'Influencers',icon:<Handshake/>},{name:'Orders',icon:<Money/>},{name:'Finance',icon:<Coin/>},{name:'Users',icon:<UsersThree/>},{name:'Settings',icon:<ShieldCheck/>},{name:'Audit',icon:<ShieldCheck/>}];const tabs=allTabs.filter(item=>allowedTabs[user.role as keyof typeof allowedTabs].includes(item.name));
 return <div className="ops-shell"><aside className="ops-sidebar"><Brand/><nav>{tabs.map(item=><button key={item.name} className={tab===item.name?'active':''} onClick={()=>setTab(item.name)}>{item.icon}{item.name}</button>)}</nav><div className="ops-account"><strong>{user.name}</strong><span>{user.role}</span><button onClick={()=>void logout()}><SignOut/> Sign out</button></div></aside><main className="ops-main"><header><div><span>Admin console</span><h1>{tab}</h1></div><button className="ops-secondary" onClick={()=>navigate('/')}><House/> View site</button></header>{error&&<Message error>{error}</Message>}{tab==='Overview'&&<div className="ops-overview"><AlertsPanel onGo={setTab}/>{metrics?<><div className="ops-metrics"><Metric label="Paid revenue" value={metrics.revenue.map(line=>formatMoney(line.cents,line.currency)).join(' + ')||'Zero'} icon={<Money/>}/><Metric label="Orders" value={metrics.orders.toLocaleString('en-IN')} icon={<Ticket/>}/><Metric label="Customers and staff" value={metrics.users.toLocaleString('en-IN')} icon={<UsersThree/>}/><Metric label="Discounts" value={metrics.discounts.map(line=>formatMoney(line.cents,line.currency)).join(' + ')||'Zero'} icon={<Percent/>}/><Metric label="Commission liability" value={formatMoney(metrics.commissionLiabilityCents)} icon={<Coin/>}/><Metric label="Applications waiting" value={metrics.pendingInfluencers.toLocaleString('en-IN')} icon={<Handshake/>}/></div><section className="ops-brief"><div><ShieldCheck size={28}/><h2>Operational controls are active</h2><p>Prices, coupons, commissions and payment events are verified by the Worker. Every sensitive admin mutation is written to the audit log.</p></div><button className="ops-primary" onClick={()=>setTab('Influencers')}>Review partners <ArrowRight/></button></section></>:<Skeleton/>}</div>}{tab==='Coupons'&&<CouponPanel reloadKey={reloadKey} onChanged={()=>setReloadKey(value=>value+1)}/>} {tab==='Influencers'&&<InfluencerPanel/>}{tab==='Orders'&&<OrderPanel canRefund={user.role==='owner'||user.role==='finance'} onChanged={()=>setReloadKey(value=>value+1)}/>} {tab==='Finance'&&<FinancePanel onChanged={()=>setReloadKey(value=>value+1)}/>}{tab==='Users'&&<UsersPanel canEdit={user.role==='owner'}/>} {tab==='Settings'&&<SettingsPanel/>}{tab==='Audit'&&<AuditPanel/>}</main></div>
}

export function InfluencerApplication(){const [done,setDone]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setError('');const form=event.currentTarget;const data=new FormData(form);try{const result=await api<{message:string}>('/api/influencers/apply',{method:'POST',body:JSON.stringify(Object.fromEntries(data))});setDone(result.message);form.reset();}catch(reason){setError(reason instanceof Error?reason.message:'Application could not be submitted')}finally{setBusy(false)}}return <main className="partner-apply"><header><Brand/><button onClick={()=>navigate('/partner')}>Partner sign in <ArrowRight/></button></header><section><span className="ops-kicker"><Handshake/> Vowvel partners</span><h1>Recommend something worth opening.</h1><p>Approved partners receive a 10% customer coupon and earn 15% on the discounted product subtotal of verified purchases.</p>{done?<div className="partner-success"><Check/><h2>Application received</h2><p>{done}</p><button className="ops-primary" onClick={()=>navigate('/partner')}>Go to sign in</button></div>:<form onSubmit={submit}><Field label="Your name"><input name="name" required/></Field><Field label="Email" helper="This email will receive sign-in codes and redemption notifications."><input name="email" type="email" required/></Field><Field label="Primary channel" helper="Instagram, YouTube, website or another public profile."><input name="channel" required/></Field><Field label="Approximate audience size"><input name="audienceSize" type="number" min="0" defaultValue="0"/></Field><Field label="Tell us about your work"><textarea name="bio" rows={4}/></Field>{error&&<Message error>{error}</Message>}<button className="ops-primary" disabled={busy}>{busy?'Submitting':'Submit application'} <ArrowRight/></button></form>}</section></main>}

export function PartnerPortal(){const [user,setUser]=useState<SessionUser|null>(null);const [checking,setChecking]=useState(true);const [data,setData]=useState<{profile:UnknownRow|null;metrics:UnknownRow;ledger:UnknownRow[]}|null>(null);const [copied,setCopied]=useState(false);useEffect(()=>{loadSession().then(session=>{if(session?.role==='influencer')setUser(session)}).catch(()=>undefined).finally(()=>setChecking(false))},[]);useEffect(()=>{if(user)api<{profile:UnknownRow|null;metrics:UnknownRow;ledger:UnknownRow[]}>('/api/partner/dashboard').then(setData).catch(()=>setData(null))},[user]);const code=String(data?.profile?.code||'');async function copy(){if(code){await navigator.clipboard.writeText(code);setCopied(true);setTimeout(()=>setCopied(false),1600)}}if(checking)return <main className="ops-loading"><Skeleton/></main>;if(!user)return <AuthPanel allowed={['influencer']} onAuthenticated={setUser} title="Your Vowvel partnership." otpArea="partner"/>;return <main className="partner-portal"><header><Brand/><div><strong>{user.name}</strong><button onClick={()=>api('/api/auth/logout',{method:'POST'}).finally(()=>setUser(null))}><SignOut/> Sign out</button></div></header><section className="partner-hero"><span className="ops-kicker"><Handshake/> Partner dashboard</span><h1>Your recommendations, accounted for.</h1><p>Follow verified conversions, commission availability and payouts without exposing customer details.</p></section>{!data?<Skeleton/>:<><section className="partner-code"><div><span>Your customer coupon</span><strong>{code||'Awaiting approval'}</strong><p>10% off for customers. You earn 15% of their discounted product subtotal. Every verified redemption is also sent to your email.</p></div>{code&&<button className="ops-primary" onClick={()=>void copy()}><Copy/> {copied?'Copied':'Copy code'}</button>}</section><div className="ops-metrics partner-metrics"><Metric label="Conversions" value={String(data.metrics.conversions||0)} icon={<Ticket/>}/><Metric label="Attributed sales" value={formatMoney(data.metrics.sales_cents)} icon={<Money/>}/><Metric label="Pending" value={formatMoney(data.metrics.pending_cents)} icon={<Coin/>}/><Metric label="Available" value={formatMoney(data.metrics.available_cents)} icon={<Check/>}/><Metric label="Paid" value={formatMoney(data.metrics.paid_cents)} icon={<Handshake/>}/></div><section className="partner-ledger"><h2>Commission ledger</h2>{data.ledger.length===0?<Empty title="No conversions yet" body="Verified purchases using your coupon will appear here."/>:<div className="ops-table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Basis</th><th>Rate</th><th>Commission</th><th>Status</th></tr></thead><tbody>{data.ledger.map(row=><tr key={String(row.id)}><td>{String(row.created_at)}</td><td>{String(row.entry_type)}</td><td>{formatMoney(row.basis_cents)}</td><td>{Number(row.rate_bps)/100}%</td><td>{formatMoney(row.amount_cents)}</td><td>{String(row.status)}</td></tr>)}</tbody></table></div>}</section></>}</main>}
